-- ==============================================================================
CREATE TABLE IF NOT EXISTS public.player_mail (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    player_id TEXT NOT NULL,
    sender_name TEXT NOT NULL DEFAULT 'Heraldo Real',
